const LINES = ['解：设未知数为 x', '由题意列方程', '移项得'];
const visual = {
  prepare: function (input) {
    var reqs = [];
    for (var i = 0; i < LINES.length; i++) {
      reqs.push({ kind: 'text', payload: LINES[i] });
    }
    return reqs;
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var m = metrics || [];
    var fontSize = 20;
    var left = 72;
    var top = 96;
    var gap = 28;
    var labels = [];
    var y = top;
    var maxW = 0;
    for (var i = 0; i < LINES.length; i++) {
      var mm = m[i] || {};
      var w = Number(mm.width) > 0 ? Number(mm.width) : LINES[i].length * fontSize * 0.95;
      var h = Number(mm.height) > 0 ? Number(mm.height) : fontSize * 1.4;
      if (w > maxW) { maxW = w; }
      labels.push({
        type: 'label',
        x: left,
        y: y + h / 2,
        text: LINES[i],
        fontSize: fontSize,
        align: 'left',
        baseline: 'middle',
        fill: '#1b2536'
      });
      y += h + gap;
    }
    var textBottom = y - gap;
    var padX = 40;
    var padY = 36;
    var fx0 = Math.max(16, left - padX);
    var fy0 = Math.max(16, top - padY);
    var fx1 = Math.min(W - 16, left + maxW + padX);
    var fy1 = Math.min(H - 16, textBottom + padY);
    var frame = visualSdk.polyline([[fx0, fy0], [fx1, fy0], [fx1, fy1], [fx0, fy1], [fx0, fy0]]);
    return {
      schemaVersion: 1,
      sceneId: 'transcribed-printed-lines',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [{ id: 'frame', commands: frame }],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'frame', stroke: '#b9c3d2', fill: '#ffffff' },
          { type: 'group', children: labels }
        ]
      }
    };
  }
};
